/**
 * Look up a manifest by tradition id + locale.
 *
 * Fallback chain:
 *   1. requested locale + requested id
 *   2. English + requested id (when a locale skipped this manifest)
 *   3. English + Aristotelian (last-resort defensive — should not happen)
 */
export function getManifest(id: TraditionId, locale: ManifestLocale = 'en'): string {
	const forLocale = MANIFESTS[locale]?.[id];
	if (forLocale) return forLocale;
	const fallbackEn = MANIFESTS.en[id];
	if (fallbackEn) return fallbackEn;
	return MANIFESTS.en.aristotelian ?? '';
}
